def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007

    if n == 0:
        return 1

    # Remove duplicates from banned strings
    banned_set = set(banned)
    # Filter out banned strings that contain any other banned string as a proper substring
    # (actually Aho-Corasick handles multiple banned strings naturally via suffix links / output markers)

    # Build Aho-Corasick automaton
    # Node structure: children dict, fail link, is_banned flag
    trie = [{}]  # trie[u][char] = child node
    is_terminal = [False]

    for word in banned_set:
        curr = 0
        for ch in word:
            if ch not in trie[curr]:
                trie[curr][ch] = len(trie)
                trie.append({})
                is_terminal.append(False)
            curr = trie[curr][ch]
        is_terminal[curr] = True

    num_nodes = len(trie)
    fail = [0] * num_nodes

    # BFS to build failure links and propagate terminal status
    from collections import deque

    queue = deque()
    for ch, child in trie[0].items():
        queue.append(child)

    while queue:
        u = queue.popleft()
        if is_terminal[fail[u]]:
            is_terminal[u] = True

        for ch, child in trie[u].items():
            f = fail[u]
            while f > 0 and ch not in trie[f]:
                f = fail[f]
            if ch in trie[f]:
                fail[child] = trie[f][ch]
            else:
                fail[child] = 0
            queue.append(child)

    # For each state and each character in alphabet, find the next state in AC DFA
    def get_next_state(u: int, ch: str) -> int:
        curr = u
        while curr > 0 and ch not in trie[curr]:
            curr = fail[curr]
        return trie[curr].get(ch, 0)

    # Collect valid (non-terminal) states reachable from root
    # Note: if root is terminal, n >= 1 cannot form any valid string
    if is_terminal[0]:
        return 0

    valid_states = [u for u in range(num_nodes) if not is_terminal[u]]
    state_to_idx = {u: i for i, u in enumerate(valid_states)}
    m = len(valid_states)

    # Transition matrix M of size m x m
    # M[j][i] = number of transitions from state i to state j
    adj = [[0] * m for _ in range(m)]
    unique_chars = sorted(list(set(alphabet)))

    for u in valid_states:
        u_idx = state_to_idx[u]
        for ch in unique_chars:
            nxt = get_next_state(u, ch)
            if not is_terminal[nxt]:
                v_idx = state_to_idx[nxt]
                adj[v_idx][u_idx] = (adj[v_idx][u_idx] + 1) % MOD

    # Matrix multiplication helper
    def mat_mul(A: list[list[int]], B: list[list[int]]) -> list[list[int]]:
        res = [[0] * m for _ in range(m)]
        for i in range(m):
            for k in range(m):
                if A[i][k]:
                    aik = A[i][k]
                    for j in range(m):
                        res[i][j] = (res[i][j] + aik * B[k][j]) % MOD
        return res

    # Matrix exponentiation helper
    def mat_pow(A: list[list[int]], p: int) -> list[list[int]]:
        res = [[int(i == j) for j in range(m)] for i in range(m)]
        base = A
        while p > 0:
            if p & 1:
                res = mat_mul(res, base)
            base = mat_mul(base, base)
            p >>= 1
        return res

    adj_pow = mat_pow(adj, n)

    # Initial vector: v[0] = 1 (root state), others 0
    start_idx = state_to_idx[0]
    total = sum(adj_pow[i][start_idx] for i in range(m)) % MOD

    return total
